<#
.SYNOPSIS
  Generate a FaultLine service package manifest.

.DESCRIPTION
  Walks a package directory (produced by one of the build\cmd\*_dist.cmd
  scripts), computes a SHA-256 for every file, and writes manifest.txt at the
  package root. The manifest is the authoritative list of files in the package:
  fl_import uses it to add, update, and -- crucially -- remove stale files in a
  consumer repository.

  The manifest is generated by walking what is actually on disk, so it can never
  drift from the files the dist script copied (provided the dist script wiped
  its output tree first).

.PARAMETER PackageDir
  Root of the package to scan (e.g. dist\memory). manifest.txt is written here.

.PARAMETER Name
  Service name recorded in the manifest (e.g. memory).

.PARAMETER Version
  Package version recorded in the manifest (e.g. 0.2.0).

.PARAMETER Depends
  Space-separated list of service names this package requires. May be empty for
  self-contained packages.
#>
[CmdletBinding(DefaultParameterSetName = 'Emit')]
param(
    [Parameter(ParameterSetName = 'Help')]
    [Alias('h')]
    [switch]$Help,

    [Parameter(ParameterSetName = 'Emit', Mandatory = $true)][string]$PackageDir,
    [Parameter(ParameterSetName = 'Emit', Mandatory = $true)][string]$Name,
    [Parameter(ParameterSetName = 'Emit', Mandatory = $true)][string]$Version,
    [string]$Depends = ""
)

$ErrorActionPreference = "Stop"

if ($Help) {
    Get-Help $PSCommandPath -Detailed
    exit 0
}

# Compute a lowercase SHA-256 hex digest using .NET directly, so we do not
# depend on Get-FileHash (absent or constrained in some PowerShell hosts).
function Get-Sha256([string]$path) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.IO.File]::ReadAllBytes($path)
        return ([BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '').ToLower()
    } finally {
        $sha.Dispose()
    }
}

if (-not (Test-Path -LiteralPath $PackageDir -PathType Container)) {
    Write-Error "Package directory not found: $PackageDir"
    exit 1
}

$root = (Resolve-Path -LiteralPath $PackageDir).Path
$manifestPath = Join-Path $root "manifest.txt"

# Everything under the package except the manifest itself and any importer
# tooling that may have been copied alongside it.
$files = Get-ChildItem -LiteralPath $root -Recurse -File |
    Where-Object { $_.Name -ne "manifest.txt" -and $_.Name -notlike "fl_import.*" }

$entries = foreach ($f in $files) {
    $rel = $f.FullName.Substring($root.Length + 1).Replace('\', '/')
    $hash = Get-Sha256 $f.FullName
    [pscustomobject]@{ Rel = $rel; Hash = $hash }
}

$lines = New-Object System.Collections.Generic.List[string]
$lines.Add("# FaultLine service package manifest")
$lines.Add("# Generated by build\dist\fl_emit_manifest.ps1 -- do not edit by hand.")
$lines.Add("name $Name")
$lines.Add("version $Version")
$lines.Add("depends $($Depends.Trim())")
$lines.Add("generated $((Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ'))")
foreach ($e in ($entries | Sort-Object Rel)) {
    $lines.Add("f $($e.Rel) $($e.Hash)")
}

# Write LF line endings and no BOM so the manifest parses identically under
# bash (sha256sum/read) and PowerShell. Set-Content -Encoding UTF8 would emit
# CRLF + a BOM on Windows PowerShell 5.1.
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($manifestPath, ($lines -join "`n") + "`n", $utf8NoBom)
Write-Host "  manifest.txt written ($(@($entries).Count) files, version $Version)"
